// eslint-disable-next-line import/no-namespace
import * as THREE from 'three'
import {OrbitControls} from 'three/examples/jsm/controls/OrbitControls'
import {GLTFLoader} from 'three/examples/jsm/loaders/GLTFLoader'
// import {toneMapping} from 'three/examples/jsm/nodes/Nodes.js'
import {observe} from '@github-ui/selector-observer'

const scene = new THREE.Scene()
const sizes = {
  width: 1280,
  height: 500,
}
const imagePath = '/images/modules/site/lab/'
const textureLoader = new THREE.TextureLoader()
const bakedTexture = textureLoader.load(`${imagePath}baked.webp`)
const matcapTexture = textureLoader.load(`${imagePath}matcap.png`)
bakedTexture.flipY = false
bakedTexture.encoding = THREE.sRGBEncoding

const bakedMaterial = new THREE.MeshMatcapMaterial({
  map: bakedTexture,
  matcap: matcapTexture,
})

const fresnelMaterial = new THREE.MeshMatcapMaterial({
  map: bakedTexture,
  matcap: matcapTexture,
})

// GLTF loader
const gltfLoader = new GLTFLoader()

gltfLoader.load(`${imagePath}copilot.glb`, gltf => {
  let headMesh: THREE.Mesh | undefined
  let earMesh: THREE.Mesh | undefined

  gltf.scene.traverse(object => {
    if (object instanceof THREE.Mesh) {
      object.material = bakedMaterial
      if (object.name === 'HeadBase') {
        headMesh = object
      } else if (object.name === 'Ears') {
        earMesh = object
      }
    }
  })

  if (headMesh !== undefined) {
    headMesh.material = fresnelMaterial
  }
  if (earMesh !== undefined) {
    earMesh.material = fresnelMaterial
  }

  gltf.scene.traverse(child => {
    if (child.name === 'Ears') {
      //earMesh = child
    }
  })

  if (headMesh !== undefined) {
    headMesh.material = fresnelMaterial
  }
  if (earMesh !== undefined) {
    earMesh.material = fresnelMaterial
  }

  scene.add(gltf.scene)
})

observe('.js-lab-copilot', canvasElement => {
  const canvas = canvasElement as HTMLCanvasElement
  const canvasRect = canvas.getBoundingClientRect()
  sizes.width = canvasRect.width
  sizes.height = canvasRect.height
  /**
   * Renderer
   */
  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: false,
    alpha: true,
  })
  const camera = new THREE.PerspectiveCamera(45, sizes.width / sizes.height, 0.1, 100)

  /* Temp cube for debugging loading
  const geometry = new THREE.BoxGeometry()
  const material = new THREE.MeshBasicMaterial({color: 0x00ff00})
  const cube = new THREE.Mesh(geometry, material)
  scene.add(cube) */

  renderer.outputEncoding = THREE.sRGBEncoding
  renderer.toneMapping = THREE.ACESFilmicToneMapping
  renderer.toneMappingExposure = 1.5
  renderer.setSize(sizes.width, sizes.height)
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))

  // Controls
  const controls = new OrbitControls(camera, canvas)
  controls.enableDamping = true

  // eslint-disable-next-line github/prefer-observers
  window.addEventListener('resize', () => {
    // Update sizes
    const boundingBox = canvas.getBoundingClientRect()
    sizes.width = boundingBox.width
    sizes.height = boundingBox.height

    // Update camera
    camera.aspect = sizes.width / sizes.height
    camera.updateProjectionMatrix()

    // Update renderer
    renderer.setSize(sizes.width, sizes.height)
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2))
  })

  /**
   * Camera
   */
  // Base camera
  camera.position.x = 4
  camera.position.y = 2
  camera.position.z = 10

  /**
   * Animate
   */

  const tick = () => {
    // Update controls
    controls.update()

    // Render
    renderer.render(scene, camera)
    // Call tick again on the next frame
    window.requestAnimationFrame(tick)
  }

  tick()
})
